function refresh(){ $('#gold').textContent=state.gold;$('#healthbar').style.width=state.hp+'%';$('#healthval').textContent=Math.round(state.hp);$('#staminabar').style.width=state.stamina+'%';$('#staminaval').textContent=Math.round(state.stamina);$('#waterbar').style.width=state.water+'%';$('#waterval').textContent=Math.round(state.water);$('#foodbar').style.width=state.food+'%';$('#foodval').textContent=Math.round(state.food);$('#ammo').textContent=state.ammo;$('#kills').textContent=state.kills;$('#missionbar').style.width=Math.min(state.kills/3*100,100)+'%';$('#level').textContent=String(state.level).padStart(2,'0');$('#xp').textContent=state.xp;save() }
const W={w:2200,h:1600,px:1100,py:800,camx:0,camy:0,keys:{},mouse:{x:0,y:0},shoot:false,day:0,items:[],zombies:[],decor:[],buildings:[],time:0,last:0,virtual:{x:0,y:0,sprint:false}};
const rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function setupWorld(){
 W.buildings=[{x:310,y:220,w:250,h:175,c:'#626253',name:'OLD MARKET'},{x:835,y:130,w:310,h:195,c:'#56594d',name:'CLINIC'},{x:1540,y:350,w:280,h:220,c:'#5a5a4d',name:'WAREHOUSE'},{x:370,y:970,w:320,h:245,c:'#4d5449',name:'SAFEHOUSE'},{x:1290,y:1030,w:380,h:245,c:'#58594e',name:'MOTOR POOL'}];
 for(let i=0;i<80;i++){let x=rand(40,W.w-40),y=rand(40,W.h-40);if(W.buildings.some(b=>x>b.x-60&&x<b.x+b.w+60&&y>b.y-55&&y<b.y+b.h+55))continue;W.decor.push({x,y,type:Math.random()<.58?'tree':Math.random()<.5?'debris':'rock',s:rand(.6,1.4)})}
 for(let i=0;i<24;i++){let x,y;do{x=rand(80,W.w-80);y=rand(80,W.h-80)}while(W.buildings.some(b=>x>b.x-40&&x<b.x+b.w+40&&y>b.y-40&&y<b.y+b.h+40)||Math.hypot(x-W.px,y-W.py)<270);W.zombies.push({x,y,hp:3,speed:rand(20,35),type:i%9===0?'armored':'common',hit:0,angle:0})}
 W.items=[{x:660,y:440,kind:'crate',name:'Military supply crate',claimed:false},{x:1500,y:730,kind:'crate',name:'Market supply box',claimed:false},{x:810,y:1190,kind:'cache',name:'Hidden cache',claimed:false},{x:1070,y:510,kind:'resource',name:'Scrap pile',claimed:false},{x:1820,y:1050,kind:'resource',name:'Wood pile',claimed:false}];
}
setupWorld();
function resize(){let r=game.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0)}new ResizeObserver(resize).observe(game);resize();
function roundRect(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.stroke()}}
function drawWorld(){const r=game.getBoundingClientRect(),w=r.width,h=r.height;ctx.clearRect(0,0,w,h);let ox=w/2-W.px,oy=h/2-W.py;W.camx=W.px-w/2;W.camy=W.py-h/2;
 ctx.fillStyle='#324536';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(ox,oy);
 // worn roads
 ctx.fillStyle='#55574c';ctx.fillRect(0,720,W.w,135);ctx.fillRect(1040,0,142,W.h);ctx.fillStyle='#757363';ctx.fillRect(0,720,W.w,4);ctx.fillRect(0,850,W.w,3);ctx.fillRect(1040,0,3,W.h);ctx.fillRect(1179,0,3,W.h);
 for(let y=740;y<W.h;y+=90){ctx.fillStyle='#9b9679';ctx.fillRect(1110,y,3,33)}for(let x=10;x<W.w;x+=85){ctx.fillStyle='#8c8974';ctx.fillRect(x,783,35,3)}
 // ground mottling
 for(let x=Math.floor(W.camx/160)*160;x<W.camx+w+150;x+=160)for(let y=Math.floor(W.camy/140)*140;y<W.camy+h+140;y+=140){let n=Math.sin(x*12.98+y*3.1)*32768%1;ctx.fillStyle=n>.5?'#465442':'#374735';ctx.globalAlpha=.13;ctx.fillRect(x+((n*100)|0),y+25,70,2);ctx.globalAlpha=1}
 for(const d of W.decor){if(d.type==='tree'){ctx.fillStyle='#1b2b21';ctx.beginPath();ctx.ellipse(d.x+7,d.y+12,21*d.s,9*d.s,0,0,7);ctx.fill();ctx.fillStyle='#253b2b';ctx.beginPath();ctx.arc(d.x,d.y-4,17*d.s,0,7);ctx.fill();ctx.fillStyle='#38513a';ctx.beginPath();ctx.arc(d.x-5,d.y-10,11*d.s,0,7);ctx.fill();ctx.fillStyle='#435941';ctx.beginPath();ctx.arc(d.x+7,d.y-2,9*d.s,0,7);ctx.fill()}else{ctx.fillStyle=d.type==='rock'?'#747363':'#665e4e';ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.s);ctx.fillRect(-10*d.s,-5*d.s,21*d.s,10*d.s);ctx.restore()}}
 for(const b of W.buildings){ctx.fillStyle='#20271f';ctx.fillRect(b.x+12,b.y+15,b.w,b.h);ctx.fillStyle=b.c;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#727162';ctx.fillRect(b.x,b.y,b.w,8);ctx.fillStyle='#393d34';for(let x=b.x+20;x<b.x+b.w-15;x+=48){ctx.fillRect(x,b.y+35,23,29);ctx.fillRect(x,b.y+b.h-55,26,26)}ctx.fillStyle='#191f1b';ctx.fillRect(b.x+b.w/2-22,b.y+b.h-35,45,35);ctx.fillStyle='#a1a184';ctx.font='10px monospace';ctx.fillText(b.name,b.x+9,b.y-8);for(let i=0;i<3;i++){ctx.strokeStyle='#52564a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(b.x+60+i*50,b.y+73);ctx.lineTo(b.x+75+i*50,b.y+89);ctx.stroke()}}
 for(const it of W.items){if(it.claimed)continue;ctx.fillStyle='#111812';ctx.fillRect(it.x-14,it.y-8,32,25);ctx.fillStyle=it.kind==='resource'?'#79745d':'#856f49';ctx.fillRect(it.x-16,it.y-12,32,23);ctx.fillStyle='#b8aa78';ctx.fillRect(it.x-16,it.y-14,32,5);if(dist(it,W)<125){ctx.fillStyle='#e5e9d8';ctx.font='11px monospace';ctx.fillText('E  '+it.name,it.x-38,it.y-23)}}
 // zombies
 for(const z of W.zombies){let a=Math.atan2(W.py-z.y,W.px-z.x);z.angle=a;ctx.save();ctx.translate(z.x,z.y);ctx.rotate(a+Math.PI/2);ctx.fillStyle='#101612';ctx.beginPath();ctx.ellipse(2,7,10,7,0,0,7);ctx.fill();ctx.fillStyle=z.type==='armored'?'#6c6860':'#788776';ctx.beginPath();ctx.ellipse(0,0,7,12,0,0,7);ctx.fill();ctx.fillStyle='#a2a292';ctx.beginPath();ctx.arc(0,-11,6,0,7);ctx.fill();ctx.fillStyle='#d66c5f';ctx.fillRect(-4,-13,2,2);ctx.fillRect(2,-13,2,2);if(z.hit>0){ctx.strokeStyle='#d96a57';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,15,0,7);ctx.stroke()}ctx.restore();if(dist(z,W)<180){ctx.fillStyle='#21231e';ctx.fillRect(z.x-10,z.y-23,20,3);ctx.fillStyle='#d66b5b';ctx.fillRect(z.x-10,z.y-23,20*z.hp/3,3)}}
 // player shadow and survivor
 ctx.fillStyle='#152019';ctx.beginPath();ctx.ellipse(W.px+3,W.py+8,15,9,0,0,7);ctx.fill();let angle=Math.atan2(W.mouse.y-h/2,W.mouse.x-w/2);ctx.save();ctx.translate(W.px,W.py);ctx.rotate(angle+Math.PI/2);ctx.fillStyle='#263a2d';ctx.beginPath();ctx.ellipse(0,1,9,12,0,0,7);ctx.fill();ctx.fillStyle='#bbc29b';ctx.beginPath();ctx.arc(0,-8,6,0,7);ctx.fill();ctx.fillStyle='#c2cf79';ctx.fillRect(-7,-3,14,9);ctx.fillStyle='#333f34';ctx.fillRect(-8,6,6,7);ctx.fillRect(2,6,6,7);ctx.fillStyle='#b5bda2';ctx.fillRect(-3,-8,8,2);ctx.restore();
 ctx.restore();}
let lastDraw=0;function frame(ts){let dt=Math.min((ts-(W.last||ts))/1000,.05);W.last=ts;W.time+=dt;update(dt);drawWorld();requestAnimationFrame(frame)}

