function buildShelter(){let a=inventory.find(i=>i.name==='Wood plank'),b=inventory.find(i=>i.name==='Scrap metal');if(!a||a.qty<4||!b||b.qty<2){toast('Need 4 Wood plank and 2 Scrap metal');return}a.qty-=4;b.qty-=2;refresh();toast('Barricade built at your safehouse');openPanel('shelter')}
function upgradeShelter(){let b=inventory.find(i=>i.name==='Scrap metal');if(state.gold<250||!b||b.qty<12){toast('Need 250 GOLD and 12 Scrap metal');return}state.gold-=250;b.qty-=12;refresh();toast('Shelter upgraded!');openPanel('shelter')}
function closePanel(){ $('#modal').classList.remove('open') }

