$$('[data-open]').forEach(b=>b.onclick=()=>openPanel(b.dataset.open));$$('[data-panel]').forEach(b=>b.onclick=()=>{$$('.nav').forEach(n=>n.classList.remove('active'));b.classList.add('active');closePanel()});$('#closeModal').onclick=closePanel;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closePanel()});
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();W.keys[k]=true;if(k==='e'||k===' ')interact();if(k==='i')openPanel('inventory');if(k==='c')openPanel('crafting');if(k==='m')openPanel('map');if(k==='escape')closePanel();if(k==='r'){state.ammo+=Math.min(12,48-state.ammo);toast('Reloaded');refresh()}if(k==='1'){let med=inventory.find(i=>i.name==='Bandage');if(med?.qty){med.qty--;state.hp=Math.min(100,state.hp+30);refresh();toast('Bandage used · health restored')}}});window.addEventListener('keyup',e=>W.keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointermove',e=>{let r=game.getBoundingClientRect();W.mouse={x:e.clientX-r.left,y:e.clientY-r.top}});canvas.addEventListener('pointerdown',e=>{if(e.button===0)shoot();else if(e.button===2)W.shoot=true});canvas.addEventListener('contextmenu',e=>e.preventDefault());
$$('[data-touch]').forEach(b=>{let action=b.dataset.touch;const down=e=>{e.preventDefault();if(action==='fire')shoot();if(action==='loot')interact();if(action==='sprint')W.virtual.sprint=true},up=()=>{if(action==='sprint')W.virtual.sprint=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
const stick=$('#stick'),knob=stick.querySelector('i');let stickId=null;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=33;if(len>max){dx*=max/len;dy*=max/len}knob.style.transform=`translate(${dx}px,${dy}px)`;W.virtual.x=dx/max;W.virtual.y=dy/max}function releaseStick(){stickId=null;W.virtual.x=W.virtual.y=0;knob.style.transform=''}
