async page => {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  const coordsBefore = await page.locator('#coords').innerText();
  await page.keyboard.down('d');
  await page.waitForTimeout(500);
  await page.keyboard.up('d');
  const coordsAfter = await page.locator('#coords').innerText();
  if (coordsBefore === coordsAfter) throw new Error('Movement did not update player coordinates');
  await page.locator('[data-open="inventory"]').click();
  if (!(await page.locator('#modal').evaluate(e => e.classList.contains('open')))) throw new Error('Inventory did not open');
  await page.locator('[data-filter="Materials"]').click();
  if (!(await page.locator('#itemgrid').innerText()).includes('Scrap metal')) throw new Error('Inventory category filter failed');
  await page.locator('#closeModal').click();
  await page.locator('[data-open="settings"]').click();
  await page.locator('#lang').selectOption('es');
  if ((await page.locator('html').getAttribute('lang')) !== 'es') throw new Error('Language selection failed');
  await page.locator('#closeModal').click();
  await page.setViewportSize({width: 390, height: 844});
  const mobile = await page.locator('#game').evaluate(e => ({width:e.clientWidth, height:e.clientHeight}));
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/ashfall.jpg'});
  if (errors.length) throw new Error('Page errors: ' + errors.join('; '));
  return {coordsBefore, coordsAfter, mobile, lang: await page.locator('html').getAttribute('lang'), canvas: await page.locator('canvas').evaluate(c=>c.toDataURL().length)};
}

