@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root {
--ink:#e8e8d9;--muted:#8b9183;--dim:#555e53;--panel:#131a17f2;--line:#344039;--lime:#c0d26a;--orange:#e89b58;--red:#d3635d;--blue:#8eb4a3;--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif;--body:'Manrope',sans-serif}

* {
box-sizing:border-box}
body {
margin:0;background:#0e1411;color:var(--ink);font-family:var(--body);overflow:hidden}
button {
font:inherit;color:inherit}
#app {
height:100dvh;min-height:560px;display:grid;grid-template-rows:68px 1fr 66px;background:#111713;position:relative;overflow:hidden}
.topbar {
display:flex;align-items:center;padding:0 28px;border-bottom:1px solid #303a33;background:#111713;gap:26px;z-index:5}
.brand {
font:800 28px var(--display);letter-spacing:2px;white-space:nowrap}
.brand span {
color:var(--lime)}
.season {
font:10px var(--mono);letter-spacing:1.6px;color:#8b978a;border-left:1px solid #3a443c;padding-left:22px}
.topright {
margin-left:auto;display:flex;align-items:center;gap:20px}
.weather {
font:11px var(--mono);color:#bac1b2}
.gold {
padding:9px 13px;border:1px solid #685d3c;background:#211f16;color:#e3c56b;font:12px var(--mono);letter-spacing:1px;display:flex;gap:9px;align-items:center}
.iconbutton {
border:1px solid var(--line);background:#1b231f;width:36px;height:36px;cursor:pointer;color:#bec6b8}
.main {
display:grid;grid-template-columns:244px 1fr 290px;min-height:0}
.sidebar {
background:#121916;border-right:1px solid #303a33;padding:19px 14px;display:flex;flex-direction:column;gap:5px;z-index:3}
.sectionlabel {
font:10px var(--mono);letter-spacing:1.5px;color:#737e72;padding:7px 10px 10px}
.nav {
height:44px;background:transparent;border:1px solid transparent;text-align:left;padding:0 12px;color:#98a294;cursor:pointer;display:flex;align-items:center;gap:12px;font-size:12px;transition:.18s}
.nav .glyph {
width:20px;text-align:center;font-size:16px;color:#869381}
.nav:hover,.nav.active {
background:#202a24;border-color:#344138;color:#e3e7d8}
.nav.active .glyph {
color:var(--lime)}
.nav .badge {
margin-left:auto;font:10px var(--mono);color:var(--orange)}
.profile {
margin-top:auto;border-top:1px solid #303a33;padding:16px 8px 0;display:flex;gap:11px;align-items:center}
.avatar {
width:39px;height:39px;background:linear-gradient(145deg,#65745c,#26372d);border:1px solid #718168;display:grid;place-items:center;color:#e0e6cb;font:700 19px var(--display)}
.profile strong {
display:block;font:600 12px var(--body)}
.profile small {
color:#8e998a;font:10px var(--mono)}
.game {
position:relative;overflow:hidden;background:#29392e;min-width:0}
.game canvas {
display:block;width:100%;height:100%;image-rendering:auto;touch-action:none}
.vignette {
position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 130px #07100ad9}
.maplabel {
position:absolute;top:20px;left:22px;background:#101713d9;border:1px solid #465148;padding:9px 12px;min-width:183px}
.maplabel small {
display:block;color:#a8b098;font:9px var(--mono);letter-spacing:1.4px;margin-bottom:3px}
.maplabel strong {
font:600 15px var(--display);letter-spacing:1px}
.danger {
color:#e18468!important}
.compass {
position:absolute;top:21px;right:22px;font:10px var(--mono);color:#c3cabc;background:#111813cf;padding:8px 10px;border:1px solid #465148}
.crosshair {
position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none;opacity:.72}
.crosshair:before,.crosshair:after {
content:'';position:absolute;background:#e3e7d6}
.crosshair:before {
width:1px;height:15px;left:8px;top:1px}
.crosshair:after {
height:1px;width:15px;top:8px;left:1px}
.hudbottom {
position:absolute;left:22px;right:22px;bottom:18px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}
.survival {
width:260px;display:grid;gap:7px}
.stat {
display:grid;grid-template-columns:20px 46px 1fr 36px;align-items:center;gap:6px;color:#bcc3b3;font:9px var(--mono)}
.stat .ico {
font-size:13px}
.bar {
height:5px;background:#161c18;border:1px solid #606b5e}
.bar i {
display:block;height:100%;background:#c2d66c}
.stat.health .bar i {
background:#d4685d}
.stat.water .bar i {
background:#79b2c2}
.stat.rad .bar i {
background:#c5b45b}
.stat span:last-child {
text-align:right}
.weapon {
background:#111813dc;border:1px solid #49554a;padding:10px 13px;min-width:150px}
.weapon small {
font:9px var(--mono);letter-spacing:1px;color:#899386}
.weapon strong {
display:block;font:600 16px var(--display);letter-spacing:1px;margin-top:3px}
.ammo {
position:absolute;right:0;bottom:-24px;color:#e4e6d9;font:11px var(--mono)}
.hint {
color:#d8dacd;background:#131a15d9;border:1px solid #55604f;padding:9px 11px;font:10px var(--mono);margin-bottom:3px}
.rightbar {
background:#121916;border-left:1px solid #303a33;padding:20px 17px;overflow:auto;z-index:3}
.paneltitle {
font:700 19px var(--display);letter-spacing:1.3px}
.panelover {
color:#899487;font:9px var(--mono);letter-spacing:1.4px;margin-top:3px}
.mission {
margin-top:19px;padding:14px 13px;border:1px solid #3c493e;background:#1a231d}
.missionhead {
display:flex;justify-content:space-between;align-items:center;font:10px var(--mono);color:#a9b49e}
.mission h3 {
font:600 16px var(--display);letter-spacing:.5px;margin:9px 0 5px}
.mission p {
font-size:10px;line-height:1.6;color:#9da697;margin:0}
.progress {
height:3px;background:#313d33;margin:12px 0 7px}
.progress i {
height:100%;display:block;width:33%;background:var(--lime)}
.progressrow {
display:flex;justify-content:space-between;color:#96a08f;font:9px var(--mono)}
.lootline {
margin-top:10px;color:#d4be6f;font:10px var(--mono)}
.divider {
border:0;border-top:1px solid #303a33;margin:19px 0}
.eventtitle {
font:10px var(--mono);letter-spacing:1.3px;color:#879286;margin-bottom:10px}
.event {
display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #263029}
.eventicon {
width:28px;height:28px;background:#222d25;display:grid;place-items:center;font-size:13px}
.event strong {
font:600 10px var(--body);display:block}
.event small {
display:block;margin-top:4px;color:#879185;font:9px var(--mono)}
.worldstat {
display:grid;grid-template-columns:1fr 1fr;gap:8px}
.worldstat div {
padding:10px;border:1px solid #303a33;background:#171e19}
.worldstat small {
display:block;font:9px var(--mono);color:#899487}
.worldstat strong {
display:block;margin-top:4px;font:600 14px var(--display)}
.footer {
background:#111713;border-top:1px solid #303a33;display:flex;align-items:center;padding:0 23px;gap:19px;z-index:5}
.key {
display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 5px;border:1px solid #535f54;background:#1d261f;color:#cbd2c2;font:10px var(--mono);margin-right:5px}
.control {
color:#a3ac9d;font-size:10px;white-space:nowrap}
.footer-right {
margin-left:auto;color:#737e72;font:9px var(--mono);letter-spacing:.5px}
.toast {
position:absolute;z-index:20;left:50%;top:78px;transform:translate(-50%,-12px);padding:11px 17px;background:#131a15ed;border:1px solid #657052;color:#e5e8d8;font:11px var(--mono);opacity:0;transition:.22s;pointer-events:none}
.toast.show {
opacity:1;transform:translate(-50%,0)}

.modal {
position:absolute;inset:0;background:#080d0bd9;z-index:12;display:none;align-items:center;justify-content:center;padding:30px;backdrop-filter:blur(4px)}
.modal.open {
display:flex}
.window {
width:min(780px,100%);max-height:88%;overflow:auto;background:#151d18;border:1px solid #4b594b;box-shadow:0 24px 80px #000a}
.windowhead {
display:flex;align-items:center;padding:18px 22px;border-bottom:1px solid #39443a}
.windowhead h2 {
font:700 24px var(--display);letter-spacing:1.5px;margin:0}
.windowhead small {
margin-left:12px;color:#879386;font:10px var(--mono)}
.close {
margin-left:auto;background:transparent;border:1px solid #586254;color:#bdc5b7;padding:7px 11px;cursor:pointer}
.windowbody {
padding:20px 22px}
.tabs {
display:flex;gap:6px;border-bottom:1px solid #39443a;margin-bottom:17px}
.tab {
border:0;background:none;color:#899487;padding:0 13px 10px;cursor:pointer;font:11px var(--mono)}
.tab.selected {
color:var(--lime);border-bottom:2px solid var(--lime)}
.itemgrid {
display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.item {
padding:12px;border:1px solid #344037;background:#1b241e;min-height:78px;cursor:pointer}
.item:hover,.item.selected {
border-color:#b4c767;background:#252e21}
.item .itemicon {
font-size:20px}
.item strong {
display:block;font:600 11px var(--body);margin-top:8px}
.item small {
font:9px var(--mono);color:#879386}
.item .qty {
float:right;color:#c4d071;font:10px var(--mono)}
.actionrow {
display:flex;justify-content:space-between;align-items:center;margin-top:16px;color:#929d8d;font:10px var(--mono)}
.action {
cursor:pointer;background:#c0d26a;color:#151c13;border:0;padding:10px 15px;font:700 11px var(--mono);letter-spacing:.5px}
.action.secondary {
background:#222c25;color:#cad2c3;border:1px solid #465247}
.craftlist {
display:grid;gap:9px}
.recipe {
border:1px solid #364239;background:#1a231d;padding:13px 14px;display:grid;grid-template-columns:40px 1fr auto;align-items:center;gap:12px}
.recipe .itemicon {
font-size:22px}
.recipe strong {
font-size:12px}
.recipe small {
display:block;color:#879386;font:9px var(--mono);margin-top:4px}
.recipe button {
font:10px var(--mono);padding:9px;background:#252e25;border:1px solid #505d4d;color:#ced5c6;cursor:pointer}
.recipe button:disabled {
opacity:.38;cursor:not-allowed}
.settingrow {
display:flex;align-items:center;justify-content:space-between;padding:15px 3px;border-bottom:1px solid #303a33;font-size:12px}
.settingrow small {
display:block;color:#899487;font-size:10px;margin-top:5px}
.settingrow select,.settingrow button {
background:#202a23;color:#d7ddce;border:1px solid #4b594c;padding:8px 10px}
.language-select {
min-width:174px}
.mapview {
height:320px;position:relative;background:repeating-linear-gradient(45deg,#26362b,#26362b 18px,#293a2d 18px,#293a2d 20px);border:1px solid #53634f;overflow:hidden}
.mapview:before {
content:'';position:absolute;inset:35% -10%;height:38px;background:#525448;transform:rotate(-18deg);border-block:3px solid #71715e}
.mapview:after {
content:'◉';position:absolute;color:#d7e678;left:49%;top:47%;font-size:22px;text-shadow:0 0 13px #d4e578}
.poi {
position:absolute;color:#d6b87b;font:10px var(--mono);background:#18221ad9;padding:5px}
.poi.one {
left:16%;top:21%}
.poi.two {
right:13%;top:27%}
.poi.three {
left:25%;bottom:18%}
.mapnote {
font:10px var(--mono);color:#8f9b8b;margin-top:12px}
.touchcontrols {
display:none;position:absolute;inset:auto 10px 16px;justify-content:space-between;align-items:flex-end;z-index:4;pointer-events:none}
.touchgroup {
display:flex;gap:7px;pointer-events:auto}
.touchbtn {
width:50px;height:50px;border-radius:50%;border:1px solid #c8d2b457;background:#172019b8;backdrop-filter:blur(3px);color:#e5e9d8;font:12px var(--mono);touch-action:none}
.touchbtn.big {
width:62px;height:62px;background:#b7c8698c;color:#f5f4e4}
.virtualstick {
width:106px;height:106px;border-radius:50%;border:1px solid #c8d2b44d;background:#1720197d;position:relative;pointer-events:auto;touch-action:none}
.virtualstick i {
position:absolute;width:37px;height:37px;border-radius:50%;left:34px;top:34px;background:#bdca9a75;border:1px solid #d6dfbc73}
.gamepad-pill {
position:absolute;right:22px;bottom:22px;z-index:6;background:#131a15dc;border:1px solid #526052;padding:7px 9px;color:#a5b19f;font:9px var(--mono);display:none}
.gamepad-pill.visible {
display:block}
.rad-alert {
position:absolute;top:65px;left:50%;transform:translateX(-50%);color:#d7c66e;font:10px var(--mono);letter-spacing:1px;text-shadow:0 1px 5px #000;pointer-events:none}
.night {
position:absolute;inset:0;pointer-events:none;background:#07101b;opacity:0;mix-blend-mode:multiply;transition:opacity 1s}
.@media(max-width:1000px) {
.main {
grid-template-columns:205px 1fr}
.rightbar {
display:none}
.topbar {
padding:0 17px}
.sidebar {
padding:14px 9px}
}
@media(max-width:680px) {
#app {
grid-template-rows:56px 1fr 52px;min-height:420px}
.main {
grid-template-columns:1fr}
.sidebar {
display:none}
.topbar {
padding:0 12px;gap:10px}
.brand {
font-size:23px}
.season {
display:none}
.weather {
display:none}
.topright {
gap:8px}
.footer {
padding:0 10px;gap:7px;overflow:auto}
.footer .control:nth-child(n+4) {
display:none}
.footer-right {
display:none}
.hudbottom {
left:11px;right:11px;bottom:131px}
.survival {
width:190px}
.maplabel {
left:10px;top:10px;min-width:0;padding:7px 9px}
.maplabel strong {
font-size:13px}
.compass {
right:10px;top:10px}
.crosshair {
display:none}
.touchcontrols {
display:flex}
.weapon {
min-width:113px;padding:8px}
.weapon strong {
font-size:14px}
.modal {
padding:12px}
.window {
max-height:94%}
.windowbody {
padding:15px}
.itemgrid {
grid-template-columns:repeat(3,1fr)}
.windowhead {
padding:14px}
.windowhead h2 {
font-size:21px}
}

